 const dialog=$('#ms-dialog');let returnFocus;
 function modal(title,body,actions=[],wide=false){returnFocus=document.activeElement;$('#ms-dialog-title').textContent=title;dialog.classList.toggle('wide',wide);$('.dialog-body').innerHTML=body+'<div id="ms-dialog-error" class="notice error" role="alert" hidden></div>';$('.dialog-foot').replaceChildren();for(const action of actions){const button=document.createElement('button');button.textContent=action.label;button.className=action.primary?'primary':action.danger?'danger':'';button.onclick=async()=>{button.disabled=true;try{await action.run(button)}catch(e){const error=$('#ms-dialog-error');error.hidden=false;error.textContent=e.message;}finally{button.disabled=false}};$('.dialog-foot').append(button);}if(!dialog.open)dialog.showModal();}
 function closeModal(){dialog.close();returnFocus?.focus();}
 $('[data-close]').onclick=closeModal;
 dialog.addEventListener('cancel',()=>{setTimeout(()=>returnFocus?.focus(),0)});
 function confirmAction(title,body,run,label='تأكيد',danger=false){modal(title,body,[{label:'رجوع',run:closeModal},{label,danger,primary:!danger,run:async()=>{await run();closeModal();}}]);}
