 function renderButtons(buttons=[]){$('#ms-buttons').innerHTML=buttons.map((b,i)=>`<fieldset data-extra-button="${i}"><legend>الزر ${i+1}</legend><div data-designer></div><div class="row panel-tools"><button type="button" data-button-move="up" data-index="${i}" ${i===0?'disabled':''}>↑ للأعلى</button><button type="button" data-button-move="down" data-index="${i}" ${i===buttons.length-1?'disabled':''}>↓ للأسفل</button><button type="button" class="danger" data-button-remove="${i}">حذف الزر</button></div></fieldset>`).join('');state.buttonDesigners=$$('#ms-buttons [data-designer]').map((container,i)=>createButtonDesigner(container,{value:buttons[i],onChange:dirty}));$('[data-action="add-button"]').disabled=buttons.length>=8;}
 function readPanels(){return $$('#ms-panels [data-design-panel]').map(row=>Object.fromEntries(['label','title','text'].map(k=>[k,row.querySelector('[data-panel-field="'+k+'"]').value])));}
 function renderPanels(panels=[]){$('#ms-panels').innerHTML=panels.map((p,i)=>`<fieldset data-design-panel="${i}"><legend>البطاقة ${i+1}</legend><div class="fields"><label>عنوان صغير<input data-panel-field="label" maxlength="60" dir="auto" value="${esc(p.label)}"></label><label>العنوان الرئيسي<input data-panel-field="title" maxlength="120" dir="auto" value="${esc(p.title)}"></label><label>النص<textarea data-panel-field="text" maxlength="400" dir="auto">${esc(p.text)}</textarea></label></div><div class="row panel-tools"><button type="button" data-panel-move="up" data-index="${i}" aria-label="تحريك البطاقة ${i+1} للأعلى" ${i===0?'disabled':''}>↑ للأعلى</button><button type="button" data-panel-move="down" data-index="${i}" aria-label="تحريك البطاقة ${i+1} للأسفل" ${i===panels.length-1?'disabled':''}>↓ للأسفل</button><button type="button" class="danger" data-panel-remove="${i}">حذف البطاقة</button></div></fieldset>`).join('')||'<p class="hint">لا توجد بطاقات في هذا القالب. أضف بطاقة لعرض موعد أو محور أو فكرة بارزة.</p>';$('[data-action="add-panel"]').disabled=panels.length>=6;}
 function syncPrimaryButton(){const enabled=$('#ms-cta-enabled').checked;$('#ms-cta-label').disabled=!enabled;$('#ms-cta-url').disabled=!enabled;}
 function designPayload(){return{designVersion:state.draft?.payload.designVersion||1,brandCaption:$('#ms-brand-caption').value,fontFamily:$('#ms-font-family').value,headingFont:$('#ms-heading-font').value,bodySize:Number($('#ms-body-size').value),headingSize:Number($('#ms-heading-size').value),lineHeight:Number($('#ms-line-height').value),buttons:state.buttonDesigners.map(d=>d.read()),brandName:$('#ms-brand-name').value,brandTagline:$('#ms-brand-tagline').value,footerText:$('#ms-footer-text').value,footerLinkLabel:$('#ms-footer-label').value,footerLinkUrl:$('#ms-footer-url').value,unsubscribeLabel:$('#ms-unsubscribe-label').value,headerEnabled:$('#ms-header-enabled').checked,footerEnabled:$('#ms-footer-enabled').checked,heroEnabled:$('#ms-hero-enabled').checked,panels:readPanels()};}
 function payload(){return{...designPayload(),shareEnabled:state.config.subscriptions>=1&&$('#ms-share-enabled').checked,shareText:$('#ms-share-text').value,shareLabel:$('#ms-share-label').value,subject:$('#ms-subject').value.trim(),preheader:$('#ms-preheader').value.trim(),message:editor.element.value,audience:$('#ms-audience').value,listId:$('#ms-list').value,courseId:$('#ms-course').value,campaignId:$('#ms-previous').value,excludeCampaignId:$('#ms-exclude').value,extraRecipients:$('#ms-recipients').value,ids:$('#ms-audience').value==='selected'?([...document.querySelectorAll('.pick:checked')].map(n=>n.dataset.id).length?[...document.querySelectorAll('.pick:checked')].map(n=>n.dataset.id):state.draft?.payload.ids||[]):[],fallbackName:$('#ms-fallback').value.trim(),plain:$('#ms-layout').value==='letter',layout:$('#ms-layout').value,eyebrow:$('#ms-eyebrow').value,headline:$('#ms-headline').value,intro:$('#ms-intro').value,logoUrl:$('#ms-logo').value.trim(),brandColor:$('#ms-brand-color').value,signature:$('#ms-signature').value,signatureEnabled:$('#ms-signature-enabled').checked,ctaLabel:$('#ms-cta-enabled').checked?$('#ms-cta-label').value.trim():'',ctaUrl:$('#ms-cta-enabled').checked?$('#ms-cta-url').value.trim():'',attachmentPath:state.draft?.payload.attachmentPath||'',scheduledAt:dubaiISO($('#ms-schedule').value)}}
 function putPayload(p={}){$('#ms-cta-enabled').checked=Boolean(p.ctaLabel||p.ctaUrl);syncPrimaryButton();$('#ms-share-enabled').checked=p.shareEnabled===true;$('#ms-share-text').value=p.shareText||'';$('#ms-share-label').value=p.shareLabel||'';$('#ms-legacy-design').hidden=p.designVersion===3;renderButtons(p.buttons||[]);$('#ms-font-family').value=p.fontFamily||'ibm';$('#ms-heading-font').value=p.headingFont||p.fontFamily||'ibm';$('#ms-body-size').value=p.bodySize||16;$('#ms-heading-size').value=p.headingSize||32;$('#ms-line-height').value=p.lineHeight||1.9;p={...mailIdentityDefaults(messageDirection(messageText(p.message||''))==='ltr'),...p};renderPanels(p.panels||[]);for(const [selector,key] of [['#ms-header-enabled','headerEnabled'],['#ms-footer-enabled','footerEnabled'],['#ms-hero-enabled','heroEnabled'],['#ms-signature-enabled','signatureEnabled']])$(selector).checked=p[key]!==false;for(const [selector,key]of [['#ms-subject','subject'],['#ms-preheader','preheader'],['#ms-recipients','extraRecipients'],['#ms-fallback','fallbackName'],['#ms-logo','logoUrl'],['#ms-signature','signature'],['#ms-cta-label','ctaLabel'],['#ms-cta-url','ctaUrl'],['#ms-eyebrow','eyebrow'],['#ms-headline','headline'],['#ms-intro','intro'],['#ms-brand-caption','brandCaption'],['#ms-brand-name','brandName'],['#ms-brand-tagline','brandTagline'],['#ms-footer-text','footerText'],['#ms-footer-label','footerLinkLabel'],['#ms-footer-url','footerLinkUrl'],['#ms-unsubscribe-label','unsubscribeLabel']])$(selector).value=p[key]||'';editor.element.value=p.message||'';updateTypography();$('#ms-audience').value=p.audience||'custom';$('#ms-list').value=p.listId||'';$('#ms-course').value=p.courseId||'';$('#ms-previous').value=p.campaignId||'';$('#ms-exclude').value=p.excludeCampaignId||'';$('#ms-brand-color').value=p.brandColor||'#1559d6';$('#ms-layout').value=p.plain?'letter':p.layout||'branded';$('#ms-schedule').value=dubaiInput(p.scheduledAt);$('#ms-attachment').value='';$('#ms-attachment-status').textContent=p.attachmentPath?'مرفق محفوظ: '+p.attachmentPath.split('/').pop().replace(/^mail-[\da-f-]+-/,''):'مستند أو صورة، حتى 10MB.';$('[data-action="remove-attachment"]').hidden=!p.attachmentPath;toggleAudience();queuePreview();}
 function saveState(text,style=''){$('#ms-save-state').textContent=text;$('#ms-save-state').className='save-state '+style;}
 function backup(){if(!state.draft)return;try{localStorage.setItem(backupKey,JSON.stringify({id:state.draft.id,version:state.draft.version,payload:payload(),updatedAt:Date.now(),editCampaign:state.editCampaign}));}catch{saveState('تعذر الحفظ المحلي؛ أبقِ الصفحة مفتوحة حتى الحفظ بالخادم.','failed');}}
 function dirty(){if(!state.draft)return;syncPrimaryButton();state.draft.payload.designVersion=3;$('#ms-legacy-design').hidden=true;updateTypography();state.seq++;backup();saveState(navigator.onLine?'تغييرات غير محفوظة…':'محفوظة مؤقتًا في هذا المتصفح');clearTimeout(state.timer);state.timer=setTimeout(()=>saveDraft().catch(()=>{}),1100);queuePreview();}
 async function saveDraft(){clearTimeout(state.timer);if(!state.draft)return null;if(state.saving){await state.saving;return state.seq===state.savedSeq?state.draft:saveDraft();}if(state.seq===state.savedSeq&&state.draft.version)return state.draft;const current=state.draft,seq=state.seq,p=payload();backup();saveState('جارٍ الحفظ…');state.saving=(async()=>{try{const saved=await call('/drafts/'+current.id,'PUT',{payload:p,version:current.version});if(state.draft?.id===current.id){state.draft=saved;state.savedSeq=seq;saveState(state.seq===seq?'تم الحفظ · '+dubai(saved.updated_at):'توجد تغييرات جديدة',state.seq===seq?'saved':'');if(state.seq===seq)localStorage.removeItem(backupKey);else backup();}return saved;}catch(e){saveState('تعذر الحفظ · المحتوى باقٍ في هذا المتصفح','failed');backup();notify(e.message,'error');throw e;}finally{state.saving=null;}})();return state.saving;}
 async function newDraft(p={}){if(state.draft&&state.seq!==state.savedSeq)await saveDraft();state.editCampaign=null;state.draft={id:id(),version:0,payload:{...state.settings,...mailIdentityDefaults(messageDirection(messageText(p.message||''))==='ltr'),...Object.fromEntries(Object.entries(state.settings).filter(([k,v])=>v!==''&&!['designVersion','layout'].includes(k))),brandCaption:'INEXC TRAINING',fontFamily:'ibm',headingFont:'ibm',shareEnabled:state.config.subscriptions>=1,shareText:state.subscriptionSettings?.shareText||'',shareLabel:state.subscriptionSettings?.shareLabel||'',...p,designVersion:3}};state.seq=0;state.savedSeq=0;putPayload(state.draft.payload);$('#ms-compose-title').textContent='رسالة جديدة';saveState('ابدأ بالكتابة؛ تُحفظ التغييرات تلقائيًا');show('compose');await loadPreviewContacts();$('#ms-subject').focus();}
 async function openDraft(draftId){if(state.draft?.id!==draftId&&state.seq!==state.savedSeq)await saveDraft();const draft=await call('/drafts/'+draftId);if(draft.campaign_id)throw Error('أُرسلت هذه المسودة؛ يمكنك نسخ الرسالة من سجل الإرسال.');state.draft=draft;state.editCampaign=null;state.seq=state.savedSeq=0;putPayload(draft.payload);$('#ms-compose-title').textContent='تحرير المسودة';saveState('تم الحفظ · '+dubai(draft.updated_at),'saved');show('compose');loadPreviewContacts();}
 async function loadPreviewContacts(){try{const data=await call('/contacts?search='+encodeURIComponent($('#ms-preview-search').value));const selected=$('#ms-preview-contact').value;$('#ms-preview-contact').innerHTML='<option value="">استخدام العبارة البديلة</option>'+data.rows.map(c=>`<option value="${c.id}">${esc(c.full_name||c.email)}</option>`).join('');$('#ms-preview-contact').value=selected;}catch{}}
 function toggleAudience(){const a=$('#ms-audience').value;$('#ms-custom-wrap').hidden=a!=='custom';$('#ms-list-wrap').hidden=a!=='list';$('#ms-course-wrap').hidden=a!=='course';$('#ms-previous-wrap').hidden=a!=='previous';$('#ms-selected-hint').hidden=a!=='selected';}
